.ds-button-primary {display: inline-flex;
  min-height: 3rem;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border: 1px solid transparent;
  border-radius: var(--radius-button);
  padding: 0.75rem 1.5rem;
  font-family: var(--font-display), sans-serif;
  font-size: 1rem;
  font-weight: 500;
  line-height: 1.4;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 160ms ease, border-color 160ms ease;background: var(--color-sakura);
  color: var(--text-on-accent);} .ds-button-primary:hover {background: var(--color-sakura-ink);} .ds-button-primary:focus-visible {outline:2px solid var(--color-sakura-ink);outline-offset:2px;} .ds-button-primary:disabled {opacity:0.55;cursor:not-allowed;} @media(prefers-reduced-motion:reduce) {.ds-button-primary {transition:none;}}

